<?php $stats = \SimpleCdn\Cdn::getStats(); $plugins = \SimpleCdn\Cdn::getPlugins(); $purgeToday = \SimpleCdn\Cdn::getPurgeLogToday(); $healthStatuses = \SimpleCdn\Cdn::getHealthStatus(); $onlineCount = 0; $offlineCount = 0; foreach ($healthStatuses as $node) { if ($node['status'] === 'online') $onlineCount++; elseif ($node['status'] === 'offline') $offlineCount++; } ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 仪表盘</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .topbar .user { font-size: 13px; color: #64748b; } .container { max-width: 1000px; margin: 24px auto; padding: 0 20px; } .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; margin-bottom: 24px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; } .card h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b; margin: 0 0 12px; } .card .value { font-size: 32px; font-weight: 700; color: #0f172a; } .card .sub { font-size: 13px; color: #64748b; margin-top: 6px; } .card .rate { font-size: 20px; margin-top: 8px; } .card .rate.ok { color: #059669; } .card .rate.warn { color: #d97706; } .section { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .section h3 { font-size: 16px; margin: 0 0 16px; color: #0f172a; } .table { width: 100%; border-collapse: collapse; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .btn { display: inline-block; padding: 8px 14px; background: #2563eb; color: #fff; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .btn-danger { background: #dc2626; } .btn-danger:hover { background: #b91c1c; } .btn-success { background: #059669; } .btn-success:hover { background: #047857; } .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 700; } .badge-cdn { background: #dbeafe; color: #1e40af; } .bypass { background: #fef3c7; color: #92400e; } .origin { background: #fee2e2; color: #991b1b; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } </style> </head> <body> <div class="topbar"> <h1>Simple CDN 后台</h1> <div class="spacer"></div> <a href="?action=logout" class="btn btn-danger" style="padding:6px 12px;font-size:12px;">退出登录</a> </div> <div class="container"> <div class="grid"> <div class="card"> <h2>总请求数</h2> <div class="value"><?php echo number_format($stats['total']); ?></div> <div class="sub">今日累计请求</div> </div> <div class="card"> <h2>命中数</h2> <div class="value"><?php echo number_format($stats['hit']); ?></div> <div class="sub">缓存命中</div> </div> <div class="card"> <h2>回源数</h2> <div class="value"><?php echo number_format($stats['origin']); ?></div> <div class="sub">未命中回源</div> </div> <div class="card"> <h2>命中率</h2> <div class="rate <?php echo $stats['rate'] >= 80 ? 'ok' : 'warn'; ?>"><?php echo $stats['rate']; ?>%</div> <div class="sub">命中 / 总请求</div> </div> <?php if (!empty($healthStatuses)): ?> <div class="card"> <h2>节点在线</h2> <div class="value <?php echo $offlineCount > 0 ? 'warn' : 'ok'; ?>"><?php echo $onlineCount; ?>/<?php echo count($healthStatuses); ?></div> <div class="sub"><?php echo $offlineCount > 0 ? $offlineCount . ' 个节点离线' : '全部节点在线'; ?></div> </div> <?php endif; ?> <div class="card"> <h2>今日清理</h2> <div class="value"><?php echo number_format($purgeToday['total']); ?></div> <div class="sub"><?php echo number_format($purgeToday['deleted']); ?> 个文件已删除</div> </div> </div> <div class="section"> <h3>插件状态</h3> <table class="table"> <thead> <tr><th style="width:40%;">插件</th><th style="width:20%;">状态</th><th>操作</th></tr> </thead> <tbody> <?php if (empty($plugins)): ?> <tr><td colspan="3" class="empty">暂无已注册插件</td></tr> <?php else: ?> <?php foreach ($plugins as $class => $enabled): ?> <tr> <td><?php echo htmlspecialchars($class); ?></td> <td><span class="badge <?php echo $enabled ? 'badge-cdn' : 'origin'; ?>"><?php echo $enabled ? '启用' : '禁用'; ?></span></td> <td> <a href="action.php?do=toggle_plugin&class=<?php echo urlencode($class); ?>&enable=<?php echo $enabled ? '0' : '1'; ?>" class="btn btn-secondary" style="padding:4px 10px;"> <?php echo $enabled ? '禁用' : '启用'; ?> </a> </td> </tr> <?php endforeach; ?> <?php endif; ?> </tbody> </table> </div> <div class="section"> <h3>快速操作</h3> <div style="display:flex;gap:12px;flex-wrap:wrap;"> <a href="stats.php" class="btn">查看详细统计</a> <a href="cache.php" class="btn">清理缓存</a> <a href="plugins.php" class="btn">管理插件</a> <a href="health.php" class="btn">节点健康检查</a> <a href="cache_warm.php" class="btn">缓存预热</a> <a href="purge_logs.php" class="btn">清理日志审计</a> <a href="nodes.php" class="btn">多节点管理</a> </div> <div class="muted" style="margin-top:12px;">提示：后台路径默认为 /admin/，可在 config.php 的 cdn_rules 中调整。</div> </div> </div> </body> </html>;